        const stats = fs.statSync(yamlFilePath);
        if (stats.size > 1048576) { // Check file size greater than 1MB
            throw new Error('File size exceeds the allowed limit.');
        }
        const yamlContent = fs.readFileSync(yamlFilePath, 'utf8');
        const yamlObject = jsYaml.load(yamlContent);
        const jsonString = JSON.stringify(yamlObject);
        return jsonString;
